package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PrimaryPowersTest {
 static final List<String> IDS=List.of("squareWhole","cubeWhole",PrimaryPowers.SQUARE,PrimaryPowers.CUBE);
 @Test public void finiteDomainsAndPublicChecking(){for(String id:IDS){assertTrue(PrimaryPowers.count(id)>=100);for(int i=0;i<PrimaryPowers.count(id);i++){Question q=PrimaryPowers.at(id,i);int[] g=PrimaryPowers.read(q);long value=g[1]==2?(long)g[0]*g[0]:(long)g[0]*g[0]*g[0];String expected;if(PrimaryPowers.added(id)){int b=0;while((g[1]==2?(long)b*b:(long)b*b*b)<g[0])b++;expected=(g[1]==2?(long)b*b:(long)b*b*b)==g[0]?"1":"0";}else expected=""+value;q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());assertFalse(new Checker().check(q,List.of(),List.of(PrimaryPowers.added(id)?expected.equals("1")?"0":"1":""+(value+1))).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("abc")).status);}}}
 @Test public void notationAndBlankRelationships(){for(String id:IDS){Question q=PrimaryPowers.at(id,10);int[] g=PrimaryPowers.read(q);HelpPlan plan=HelpPlan.forQuestion(q);assertFalse(plan.canTransfer());List<String> values=new ArrayList<>();if(PrimaryPowers.added(id)){int b=PrimaryPowers.lower(g[0],g[1]);values.add(""+g[0]);values.add(""+b);values.add(""+PrimaryPowers.power(b,g[1]));if(PrimaryPowers.power(b,g[1])!=g[0])values.add(""+PrimaryPowers.power(b+1,g[1]));values.add(PrimaryPowers.answer(id,g[0],g[1]));assertEquals(PrimaryPowers.power(b,g[1])==g[0]?4:5,plan.size());}else{assertTrue(q.prompt.endsWith(g[1]==2?"²":"³"));values.add(""+g[0]);values.add(""+g[1]);values.add(""+PrimaryPowers.power(g[0],2));if(g[1]==3)values.add(""+PrimaryPowers.power(g[0],3));}for(int i=0;i<plan.size();i++){assertTrue(plan.step(i).accepts(values.get(i)));assertFalse(plan.step(i).accepts(""));}if(!PrimaryPowers.added(id))assertEquals("두 수의 곱 B = a × a = ",plan.step(2).before);}}
 @Test public void normalPlacementFreshConditionsAndChoicePositions(){var pack=GlobalCurriculum.packs("GB").stream().filter(p->p.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(String id:IDS){assertTrue(pack.inGrade(id,5));Generator gen=new Generator(new Random(171));List<String> recent=new ArrayList<>();Set<Integer> positions=new HashSet<>();Set<String> classifications=new HashSet<>();int positive=0;for(int i=0;i<100;i++){Question q=gen.next(id,recent,true,GlobalCurriculum.limits(pack.id,id,5));assertTrue(PrimaryPowers.selected(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());positions.add(q.correctChoice);classifications.add(q.answers[0]);if(q.answers[0].equals("1"))positive++;assertFalse(HelpPlan.forQuestion(q).canTransfer());}if(PrimaryPowers.added(id)){assertEquals(Set.of(0,1),positions);assertEquals(Set.of("0","1"),classifications);assertTrue(positive>=25&&positive<=75);}}assertFalse(Curriculum.inCurriculum(Catalog.get(PrimaryPowers.SQUARE),2022));}
 @Test public void legacyAndMalformedAreSeparate(){assertFalse(PrimaryPowers.selected(new Question("cubeWhole","(5)^3","5^3","125")));for(String prompt:List.of("101²","4³","2^2")){Question q=new Question("squareWhole",prompt,"","16");assertEquals(Checker.Status.INPUT_NEEDED,PrimaryPowers.check(q,List.of("16")).status);}Question zero=PrimaryPowers.at("cubeWhole",0);assertTrue(new Checker().check(zero,List.of(),List.of("0")).correct());}
 @Test public void recognitionFullRangeFreshAndEndpointHelp(){
  for(String id:List.of(PrimaryPowers.SQUARE,PrimaryPowers.CUBE)){
   int endpoint=id.equals(PrimaryPowers.SQUARE)?100:1000,e=id.equals(PrimaryPowers.SQUARE)?2:3;CurriculumLimits limits=new CurriculumLimits("powerRecognitionRange=true;minGiven=0;maxGiven="+endpoint+";maxResult=1;nonnegative=true");Map<String,Integer>recent=new LinkedHashMap<>();Random pinned=new Random(){@Override public int nextInt(int bound){return 0;}};Set<Integer>seen=new HashSet<>();for(int i=0;i<=endpoint;i++){Question q=PrimaryPowers.next(id,pinned,limits,recent);int n=PrimaryPowers.read(q)[0];assertTrue(seen.add(n));recent.put(q.signature(),i);int b=0;while(PrimaryPowers.power(b,e)<n)b++;String expected=PrimaryPowers.power(b,e)==n?"1":"0";q.answers=new String[]{"poison"};q.expression="poison";assertTrue(PrimaryPowers.check(q,List.of(expected)).correct());}assertEquals(endpoint+1,seen.size());assertEquals(0,(int)recent.get(PrimaryPowers.next(id,pinned,limits,recent).signature()));
   for(int n:new int[]{0,endpoint}){Question q=PrimaryPowers.recognition(id,n);assertNotNull(PrimaryPowers.read(q));assertEquals(4,q.studyGuide.frames.size());assertEquals("primary-powers-recognition-v2",q.studyGuide.teachingVersion);assertFalse(q.studyGuide.transfer);assertTrue(q.studyGuide.frames.stream().noneMatch(f->f.instruction.contains("1 큰")));assertTrue(q.studyGuide.frames.stream().noneMatch(f->f.expected.equals(""+PrimaryPowers.power(11,e))));}
   Question general=PrimaryPowers.recognition(id,endpoint-3);assertNotNull(PrimaryPowers.read(general));assertEquals(5,general.studyGuide.frames.size());assertEquals(""+endpoint,general.studyGuide.frames.get(3).expected);
   assertNull(PrimaryPowers.read(new Question(id,(id.equals(PrimaryPowers.SQUARE)?10001:1000001)+"은 "+(e==2?"제곱수":"세제곱수")+"인가요?","","0")));
  }
 }
 @Test public void oldUpperPowerInputCannotBecomeNewRecognitionChoice(){Question q=PrimaryPowers.recognition(PrimaryPowers.SQUARE,0);HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.teachingVersion="primary-powers-v1";old.stage=4;old.entries=new ArrayList<>(List.of("0","0","0","1"));HelpPlan.Draft resumed=HelpPlan.forQuestion(q).restore(old,q.id);assertEquals(0,resumed.stage);assertEquals(List.of(""),resumed.entries);assertEquals("primary-powers-recognition-v2",resumed.teachingVersion);assertEquals("1",q.answers[0]);}
}
